SET client_encoding = 'UTF8';
BEGIN;
SET search_path TO public, pg_catalog;

-- ════════════════════════════════════════════════════════════════════════
-- 09_seed_data.sql  (REPLACEMENT VERSION)
-- 3 tenants x 10 orgs x 7 users x 100 leads = 30 orgs, 210 org users + 3
-- tenant admins + 1 super admin, 3000 leads, ~75 campaigns, ~3876
-- interactions, ~1530 follow-ups, ~675 history rows.
--
-- This file is a DROP-IN REPLACEMENT for the original 09_seed_data.sql.
-- Run it INSTEAD OF the original — do not run both in the same database,
-- the original 09_seed_data.sql's FitClass/Velvet Boutique sample rows are
-- superseded by the fuller 10-org versions of those same two tenants here.
--
-- PREREQUISITE FIX — user_roles seed typo:
-- 02_lookup_tables.sql currently seeds the role name as
-- 'sales_representativeresentative' (a copy-paste typo) instead of
-- 'sales_representative'. Every subquery in the ORIGINAL 09_seed_data.sql
-- that does (SELECT id FROM user_roles WHERE name = 'sales_representative')
-- resolves to NULL because of this, which means role_id NOT NULL inserts
-- for every sales rep in the original seed file would fail on a true
-- from-scratch run. This script corrects the lookup row in-place (idempotent
-- UPDATE) before inserting any users, so every 'sales_representative'
-- subquery below resolves correctly. The fix is also safe to leave applied
-- permanently — it does not change the typo's rank/label/description.
-- ════════════════════════════════════════════════════════════════════════

UPDATE user_roles
   SET name = 'sales_representative'
 WHERE name = 'sales_representativeresentative';

-- ── Lookup extension: internal_note interaction type (carried over) ──────
INSERT INTO interaction_types (name, description)
VALUES ('internal_note', 'Internal note or annotation added by a team member')
ON CONFLICT (name) DO NOTHING;

-- ── Lookup extension: hotel_property org type (new, for ITC Hotels) ──────
INSERT INTO org_types (name, description)
VALUES ('hotel_property', 'Hotel or resort property location')
ON CONFLICT (name) DO NOTHING;

-- ── Geography extension: states + cities beyond the original 14-city seed
-- (ON CONFLICT DO NOTHING — layers on top of 02_lookup_tables.sql safely) ─
INSERT INTO states (country_id, name, code)
SELECT c.id, s.name, s.code
FROM countries c
CROSS JOIN (VALUES
    ('Maharashtra', 'MH'),
    ('Karnataka', 'KA'),
    ('Tamil Nadu', 'TN'),
    ('West Bengal', 'WB'),
    ('Telangana', 'TS'),
    ('Gujarat', 'GJ')) AS s(name, code)
WHERE c.iso_code = 'IN'
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO cities (state_id, name)
SELECT s.id, c.name
FROM states s
CROSS JOIN (VALUES
    ('Maharashtra', 'Mumbai'),
    ('Maharashtra', 'Pune'),
    ('Maharashtra', 'Nagpur'),
    ('Karnataka', 'Bengaluru'),
    ('Karnataka', 'Mysuru'),
    ('Tamil Nadu', 'Chennai'),
    ('Tamil Nadu', 'Coimbatore'),
    ('West Bengal', 'Kolkata'),
    ('West Bengal', 'Howrah'),
    ('Telangana', 'Hyderabad'),
    ('Telangana', 'Warangal'),
    ('Gujarat', 'Ahmedabad'),
    ('Gujarat', 'Surat'),
    ('Delhi', 'Vasant Kunj'),
    ('Delhi', 'Karol Bagh'),
    ('Delhi', 'Pitampura'),
    ('Haryana', 'Gurgaon Sector 29'),
    ('Haryana', 'Panchkula')) AS c(state_name, name)
WHERE s.name = c.state_name
ON CONFLICT (state_id, name) DO NOTHING;

