-- ============================================================
-- POPULATE user_org_access BEFORE LEADS
-- check_lead_fk_org_scope() validates assigned_user_id against
-- user_org_access, so this must run before any marketing_leads INSERTs.
-- ON CONFLICT DO UPDATE makes re-runs idempotent.
-- ============================================================
INSERT INTO user_org_access (user_id, org_id, role_id, granted_by)
SELECT u.id, u.org_id, u.role_id, NULL::uuid
FROM users u
WHERE NOT u.is_deleted
ON CONFLICT (user_id, org_id) DO UPDATE
    SET role_id    = EXCLUDED.role_id,
        updated_at = CLOCK_TIMESTAMP();

